#!/bin/sh
# Agent-facing `gog` (installed as /usr/local/bin/gog). Generated by the assistant (M4, Nov 13).
# Sending is ALWAYS blocked here (--gmail-no-send; verified with v0.47.1: gmail send, gmail drafts send
# and the `send` shortcut exit 2 before any auth or network call). The only send path is the
# send-email wrapper (allowlist + human approval), which calls the real binary directly.
# --no-input: never wait for a prompt inside an agent tool call.
set -eu
REAL=/usr/local/lib/gogcli/gog
PW_FILE="${HOME:-/home/agent}/.config/a3/gog-keyring-password" # 0600, local disk, written by startup.sh
if [ -z "${GOG_KEYRING_PASSWORD:-}" ] && [ -r "$PW_FILE" ]; then
  GOG_KEYRING_PASSWORD="$(cat "$PW_FILE")"
  export GOG_KEYRING_PASSWORD
fi
exec "$REAL" --gmail-no-send --no-input "$@"
